static int CountCommas(ReadOnlySpan<char> line)
{
    var n = 0;
    foreach (var c in line)
    {
        if (c == ',') n++;
    }
    return n;
}

static async Task<int> CountCommasAsync(ReadOnlyMemory<char> rented, CancellationToken ct)
{
    await Task.Yield();
    ct.ThrowIfCancellationRequested();
    return CountCommas(rented.Span);
}

